values
  ('mcdonalds', 'McDonald''s', ARRAY['McDo','Mc Donalds']::text[], 'restaurant', null, 'La franchise McDonald’s Israel a annoncé avoir offert des repas à des soldats israéliens après le 7 octobre 2023. OUMMAH classe l’enseigne à boycotter sur ce lien documenté.', 'material_support', '[{"label":"Reuters — repas offerts par McDonald’s Israel","url":"https://www.reuters.com/fact-check/mcdonalds-did-not-congratulate-israeli-military-over-gaza-killings-2024-04-03/","publishedAt":"2024-04-03"},{"label":"BDS — campagnes de boycott","url":"https://www.bdsmovement.net/get-involved-boycott"}]'::jsonb, '{}'::text[], '{}'::text[], '{}'::text[], '2026-09-04T00:00:00Z'::timestamptz, true),
  ('coca-cola', 'Coca-Cola', ARRAY['Coke','Coca Cola']::text[], 'beverage', 'The Coca-Cola Company', 'Coca-Cola figure parmi les campagnes de boycott soutenues par BDS. OUMMAH applique sa règle interne : tout lien documenté retenu entraîne le statut À boycotter.', 'occupation_economy', '[{"label":"BDS — campagnes de boycott","url":"https://www.bdsmovement.net/get-involved-boycott"},{"label":"DBIO / BDS — entreprises impliquées","url":"https://bdsmovement.net/news/new-dbio-report-finds-european-financial-sector-directly-funding-companies-implicated-israel%E2%80%99s"}]'::jsonb, '{}'::text[], '{}'::text[], '{}'::text[], '2026-09-04T00:00:00Z'::timestamptz, true),
  ('pizza-hut', 'Pizza Hut', '{}'::text[], 'restaurant', 'Yum! Brands', 'Pizza Hut figure parmi les campagnes populaires de boycott soutenues par BDS en raison d’actions attribuées à sa branche ou ses franchisés en Israël.', 'subsidiary_or_franchise', '[{"label":"BDS — guide boycott","url":"https://www.bdsmovement.net/ar/Guide-to-BDS-Boycott"},{"label":"Yum! Brands — portefeuille","url":"https://www.yum.com/wps/portal/yumbrands/Yumbrands/company/about-us"}]'::jsonb, '{}'::text[], '{}'::text[], '{}'::text[], '2026-09-04T00:00:00Z'::timestamptz, true),
  ('kfc', 'KFC', ARRAY['Kentucky Fried Chicken']::text[], 'restaurant', 'Yum! Brands', 'KFC appartient à Yum! Brands. OUMMAH applique le statut rouge par héritage de groupe lorsqu’un lien documenté touche une marque du même groupe ; la fiche distingue ce lien indirect d’un financement militaire direct.', 'parent_group', '[{"label":"BDS — Pizza Hut parmi les campagnes soutenues","url":"https://www.bdsmovement.net/ar/Guide-to-BDS-Boycott"},{"label":"Yum! Brands — KFC, Pizza Hut, Taco Bell et Habit","url":"https://www.yum.com/wps/portal/yumbrands/Yumbrands/company/about-us"}]'::jsonb, '{}'::text[], '{}'::text[], '{}'::text[], '2026-09-04T00:00:00Z'::timestamptz, true),
  ('taco-bell', 'Taco Bell', '{}'::text[], 'restaurant', 'Yum! Brands', 'Taco Bell appartient à Yum! Brands. OUMMAH applique ici son classement par groupe : le lien documenté retenu concerne une autre marque du même groupe, Pizza Hut.', 'parent_group', '[{"label":"BDS — Pizza Hut parmi les campagnes soutenues","url":"https://www.bdsmovement.net/ar/Guide-to-BDS-Boycott"},{"label":"Yum! Brands — portefeuille","url":"https://www.yum.com/wps/portal/yumbrands/Yumbrands/company/about-us"}]'::jsonb, '{}'::text[], '{}'::text[], '{}'::text[], '2026-09-04T00:00:00Z'::timestamptz, true),
